import runtime as rt
from pathlib import Path
import time,hashlib,shutil
import numpy as np,pandas as pd,anndata as ad,lance
from scipy import sparse
from public_store import PublicStore
name='HCT116';base='HCT116_search';task='HCT116_rich_search';folder=Path('artifacts/tasks');path=folder/(task+'.h5ad');manifest=rt.json.loads((folder/'manifest.json').read_text())
if path.exists() and path.with_suffix('.json').exists() and task in manifest:raise SystemExit('Existing certified rich panel')
oldsel=pd.read_parquet(folder/(base+'_selection.parquet'));cells=pd.read_parquet(f'artifacts/{name}_cells.parquet');v=pd.read_parquet(f'artifacts/{name}_genes.parquet');off=np.load(f'artifacts/{name}_offset_mapping.npz');assert np.array_equal(v.gene_integer_id.to_numpy(),np.arange(len(v)));cells=cells[off['logical_start'][cells.cell_integer_id.to_numpy()//5000]>=0].copy();assert cells.pass_guide_filter.all();extra=[]
for t in manifest[base]['targets']:
 old=oldsel.loc[oldsel.target_gene.astype(str)==t,'cell_integer_id'];available=cells[(cells.gene_target.astype(str)==t)&~cells.cell_integer_id.isin(old)];n=min(400,len(available)+len(old))-len(old);seed=int.from_bytes(hashlib.sha256(('rich:'+t).encode()).digest()[:8],'little');rng=np.random.default_rng(seed)
 if n:extra.append(available.iloc[rng.choice(len(available),n,replace=False)])
selected=pd.concat(extra).sort_values('cell_integer_id').reset_index(drop=True);selected['target_gene']=selected.gene_target.astype(str);selected['batch']=selected['sample'].astype(str);selected['evaluation_role']='perturbation';selected['source_row']=selected.cell_integer_id.to_numpy();selected.to_parquet(folder/(task+'_additional_selection.parquet'));oldsel['source_row']=oldsel.cell_integer_id.to_numpy();combined=pd.concat([oldsel,selected],ignore_index=True).sort_values('cell_integer_id').reset_index(drop=True);assert combined.cell_integer_id.is_unique;combined.to_parquet(folder/(task+'_selection.parquet'));base_data=ad.read_h5ad(folder/(base+'.h5ad'),backed='r');genes=base_data.var_names.to_numpy(str);mapping=pd.Index(genes).get_indexer(v.gene_id.to_numpy(str));prior=rt.json.loads(Path(f'artifacts/{name}_raw_transfer.json').read_text())['bytes'];receipt=Path('artifacts/HCT116_rich_transfer.json');previous=rt.json.loads(receipt.read_text())['bytes_additional'] if receipt.exists() else 0;p=PublicStore();p.byte_cap=3_000_000_000-prior-previous;assert p.byte_cap>0;blocks=[];start=time.time();print('Additional cells',len(selected),'reference range',combined[combined.evaluation_role=='perturbation'].groupby('target_gene',observed=True).size().describe().to_dict(),flush=True)
try:
 e=lance.dataset('s3://public/data/HCT116/expression.lance',version=int(off['version']),storage_options=p.options(),block_size=4096)
 for lo in range(0,len(selected),128):
  rt.guard(2*1024**3);rr=selected.iloc[lo:lo+128];length=rr.n_genes_by_counts.to_numpy(np.int64);ids=rr.cell_integer_id.to_numpy(np.int64);g=ids//5000;starts=rr.cell_start_index.to_numpy(np.int64)-off['original_start'][g]+off['logical_start'][g];ix=np.concatenate([np.arange(s,s+n,dtype=np.uint64) for s,n in zip(starts,length)]);tab=e.take(ix,columns=['cell_integer_id','gene_integer_id','value']);local=np.repeat(np.arange(len(rr)),length);np.testing.assert_array_equal(tab['cell_integer_id'].to_numpy(),np.repeat(ids,length));value=tab['value'].to_numpy();assert np.equal(value,np.floor(value)).all() and (value>=0).all();np.testing.assert_array_equal(np.bincount(local,weights=value,minlength=len(rr)),rr.total_counts.to_numpy());cols=mapping[tab['gene_integer_id'].to_numpy()];keep=cols>=0;blocks.append(sparse.csr_matrix((value[keep].astype(np.int32),(local[keep],cols[keep])),shape=(len(rr),len(genes))));rt.save(receipt,dict(bytes_additional=previous+p.bytes,bytes_original=prior,rows_done=min(lo+128,len(selected)),extra_cells=len(selected),status='in progress'))
  if lo%1280==0:print(lo,len(selected),'GB',round((previous+p.bytes)/1e9,3),'seconds',round(time.time()-start),flush=True)
finally:
 p.close();rt.save(receipt,dict(bytes_additional=previous+p.bytes,bytes_original=prior,rows_done=sum(x.shape[0] for x in blocks),extra_cells=len(selected),status='connection closed'))
# Combine retained exact matrices with newly fetched cells. Never synthesize reference cells.
oldblocks=[]
for lo in range(0,base_data.n_obs,512):oldblocks.append(sparse.csr_matrix(base_data.X[lo:lo+512]))
oldids=base_data.obs.cell_integer_id.to_numpy();matrix=sparse.vstack(oldblocks+blocks,format='csr');ids=np.r_[oldids,selected.cell_integer_id.to_numpy()];order=np.argsort(ids);assert np.array_equal(ids[order],combined.cell_integer_id.to_numpy());matrix=matrix[order];matrix.sum_duplicates();matrix.sort_indices();obs=combined[['target_gene','batch','evaluation_role','source_row','cell_integer_id']].copy();obs.index=[f'HCT116_{i}' for i in combined.cell_integer_id];a=ad.AnnData(matrix,obs=obs,var=pd.DataFrame(index=genes));a.uns['evaluation_only']=True;counts=combined[combined.evaluation_role=='perturbation'].groupby('target_gene',observed=True).size();assert counts.min()>=64 and counts.max()<=400
# Verify both control arms remained exactly the same real counts, in source-cell order.
for role in ['input_control','reference_control']:
 ids0=base_data.obs.loc[base_data.obs.evaluation_role.astype(str)==role,'cell_integer_id'].to_numpy();lookup=pd.Index(a.obs.cell_integer_id).get_indexer(ids0);oldlookup=pd.Index(base_data.obs.cell_integer_id).get_indexer(ids0)
 for lo in range(0,len(ids0),128):assert (a.X[lookup[lo:lo+128]]!=base_data.X[oldlookup[lo:lo+128]]).nnz==0
base_data.file.close();temp=path.with_suffix('.partial.h5ad');a.write_h5ad(temp,compression='gzip',compression_opts=1);temp.replace(path);rt.save(path.with_suffix('.json'),dict(sha256=rt.sha(path),parent_sha256=rt.sha(folder/(base+'.h5ad')),bytes_additional=previous+p.bytes,readout_policy='measured official intersection',version=int(off['version']),control_counts_exactly_retained=True,reference_cells_per_target=counts.to_dict(),selection_sha256=rt.sha(folder/(task+'_selection.parquet'))))
m=dict(manifest[base]);m.update(source='orion_raw_rich',parent_task=base,n_real=counts.to_dict(),selection_sha256=rt.sha(folder/(task+'_selection.parquet')),reference_precision='Original 64 cells plus availability-only additions up to 400; same target panel and controls',eligible_for_primary_calibration=True);batches=sorted(combined.batch.unique());control=combined[combined.evaluation_role=='reference_control'].batch.value_counts().reindex(batches,fill_value=0);q=control.to_numpy()/control.sum();l1={t:float(np.abs(combined[(combined.target_gene==t)&(combined.evaluation_role=='perturbation')].batch.value_counts().reindex(batches,fill_value=0).to_numpy()/counts[t]-q).sum()) for t in m['targets']};m['audit']=dict(m['audit'],per_target_control_mixture_L1=l1);shutil.copyfile(folder/'manifest.json',folder/'manifest_before_rich.json');manifest[task]=m;rt.save(folder/'manifest.json',manifest);print('DONE',task,a.shape,'cells per target',counts.describe().to_dict(),flush=True)
